#include <stdio.h>

typedef struct { int year, month, day; } Date;

int main(void) {
    Date date;
    int days[] = {31,28,31,30,31,30,31,31,30,31,30,31};
    scanf("%d%d%d", &date.year, &date.month, &date.day);
    if (date.year % 400 == 0 || (date.year % 4 == 0 && date.year % 100 != 0)) days[1] = 29;
    int result = date.day;
    for (int i = 0; i < date.month - 1; i++) result += days[i];
    printf("%d\n", result);
    return 0;
}
